-- PT102-S4-Q14. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT102-S4-Q14$batch09$ AND q.stimulus=$batch09$We have a moral obligation not to destroy books, even if they belong to us. The reason is quite simple: If preserved, books will almost certainly contribute to the intellectual and emotional enrichment of future generations.$batch09$ AND q.prompt=$batch09$Which one of the following most accurately expresses the principle underlying the argument?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT102-S4-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT102-S4-Q14$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S4-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT102-S4-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$We have a moral obligation not to destroy books, even our own.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$If preserved, books will almost certainly enrich future generations, intellectually and emotionally.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The argument moves from "this thing will very likely enrich people who come after us" to "we're obligated not to destroy it." The principle has to have that fact on the left and the obligation not to destroy on the right: if something will very likely enrich posterity, we must not destroy it.$batch09$), (3, $batch09$Goal$batch09$, $batch09$If a thing will most likely enrich future generations, we are morally obligated not to destroy it.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT102-S4-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This is the trap, picked by 14%. It sounds generous and moral, but look at what it obligates: devoting effort to performing actions. The conclusion is a duty to refrain, not to perform. A also lowers the bar to "at least some chance", while the evidence says "almost certainly". Even if we accept A, we only learn we should work on helpful projects. We still don't have a rule about destroying anything.$batch09$), ($batch09$B$batch09$, $batch09$The evidence is about what books will do for the future, not about what past generations saved for us. Nothing says these books were preserved by anyone before us.$batch09$), ($batch09$C$batch09$, $batch09$The argument never sets future generations against the present one. Keeping your own book doesn't cost the present generation anything the argument mentions.$batch09$), ($batch09$D$batch09$, $batch09$"Will most likely enrich" matches "almost certainly contribute to the enrichment", "posterity" matches "future generations", and the right side is exactly the conclusion: an obligation not to destroy. Apply it to books and the conclusion follows.$batch09$), ($batch09$E$batch09$, $batch09$This requires that the thing benefit "someone we know." Future generations are people we will never meet, so E would actually block the conclusion.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT102-S4-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
